var filters = require('./components/filters');


function mapLink(linkFilters) {
    return '/?' + $.param(filters.toParams(linkFilters));
}


function init () {
    $('.map-link').each(function () {
        $(this).attr('href', mapLink($(this).data()));
    });
}

$(document).ready(init);

module.exports = {
    init: init
};

